// 1. Marks stale + refetches active observers
await queryClient.invalidateQueries({ queryKey: ['todos'] });

// 2. Forces immediate refetch even if fresh (ignores staleTime)
await queryClient.refetchQueries({ queryKey: ['todos'], type: 'active' });

// 3. Clears data back to initialData / undefined and refetches active
await queryClient.resetQueries({ queryKey: ['todos'] });

// 4. Synchronous direct cache write (must be immutable)
queryClient.setQueryData<Todo[]>(['todos'], (old) =>
  old ? [...old, newTodo] : [newTodo]
);

