await queryClient.resetQueries({ queryKey: ['todos'] });

// 4. Synchronous direct cache write (must be immutable)
queryClient.setQueryData<Todo[]>(['todos'], (old) =>
  old ? [...old, newTodo] : [newTodo]
);

