// Dynamic backoff polling: starts at 1s, doubles on each incomplete poll up to 16s
useQuery({
  queryKey: ['export-task', taskId],
  queryFn: () => fetchExportTask(taskId),
  refetchInterval: (query) => {
    if (query.state.data?.done) return false;
    const polls = query.state.dataUpdateCount;
    return Math.min(1000 * 2 ** polls, 16_000);
  },
});

