const queryClient = new QueryClient({
  queryCache: new QueryCache({
    onSuccess: (data, query) => {
      // Fires ONCE per network fetch, never duplicated across mounted components
      analytics.track('query_resolved', {
        queryHash: query.queryHash,
        observers: query.getObserversCount(),
        updateCount: query.state.dataUpdateCount,
      });
    },
    onSettled: (data, error, query) => {
      if (query.meta?.auditTag) {
        logger.debug(`Settled [${query.queryHash}]`, { hasError: Boolean(error) });
      }
    },
  }),
});

